let advisorPreview=0,sourceOpen=false,reportOpen=false,immersive=false;
const stageNames={brief:'Briefing',situation:'Situation',agents:'Advisor',evidence:'Evidence',decision:'Decision',outcome:'Outcome',debrief:'Debrief'};
function tone(){ /* Action cues are handled by the shared audio engine. */ }
function controls(){return `<button class="icon-btn audio-toggle" data-mobile="music" aria-label="${gameAudio.music?'Mute music':'Enable music'}" aria-pressed="${gameAudio.music}"><span>♫</span><small>MUSIC</small></button><button class="icon-btn audio-toggle" data-mobile="effects" aria-label="${gameAudio.effects?'Mute effects':'Enable effects'}" aria-pressed="${gameAudio.effects}"><span>◖))</span><small>SFX</small></button><button class="icon-btn" data-mobile="fullscreen" aria-label="Toggle immersive mode">⛶</button>`;}
function gameButton(label,action,secondary=false){return btn(label,action,secondary?'secondary':'');}
function mobileView(){let body='',dock='',kicker='',title='',subtitle='';const a=agents[state.agent??0];switch(state.screen){
case 'brief':kicker='60s DECISIONS / EPISODE 01';title='STORM<br><span>CORRIDOR</span>';subtitle='NAVAL DECISION SIMULATION';body=`<div class="mission-crest">◈</div><div class="brief-story">A storm ahead. A deadline closing in.<br>Assess the evidence and decide your crew’s fate.</div><div class="mission-chips"><span>◷ Timer disabled</span><span>◈ 3 AI advisors</span><span>▤ 6 clues</span></div>`;dock=gameButton('BEGIN OPERATION　→','start')+`<small>No time limit · Music & SFX controls in the top bar</small>`;break;
case 'situation':kicker='MV MERIDIAN / 14:30 UTC';title='Storm closing in';subtitle='Keep the crew safe. Protect the delivery window.';body=`<div class="mini-stats"><div><small>GUSTS</small><b>48 <em>kn</em></b></div><div><small>WAVES / LIMIT 3.5 m</small><b class="bad">4.8 <em>m</em></b></div><div><small>TIME MARGIN</small><b>30 <em>min</em></b></div></div><div class="tactical-window">${map()}</div><div class="radio"><i>◉</i><p><b>BRIDGE REPORT</b>Storm moving northwest. The eastern corridor is open. Holding position may put us in its path.</p></div>`;dock=gameButton('CONSULT AI ADVISOR　→','agents');break;
case 'agents':{const p=agents[advisorPreview];kicker='ADVISOR LINK / CHOOSE ONE';title='Choose your advisor';subtitle='They advise. You command.';body=`<div class="advisor-carousel"><button class="arrow" data-mobile="previous" aria-label="Previous advisor">‹</button><article class="advisor-card"><div class="portrait portrait-${p.id}"><span>${p.symbol}</span><div class="orbit"></div><small>NEURAL LINK / 0${advisorPreview+1}</small></div><h2>${p.name}</h2><div class="advisor-type">${p.type}</div><p>${p.desc}</p><div class="bias"><small>KNOWN BLIND SPOT</small>${p.bias}</div></article><button class="arrow" data-mobile="next" aria-label="Next advisor">›</button></div><div class="dots">${agents.map((x,i)=>`<button data-mobile="preview:${i}" class="${i===advisorPreview?'selected':''}" aria-label="View ${x.name}"></button>`).join('')}</div>`;dock=gameButton(`SELECT ${p.name}`,'agent:'+advisorPreview);break;}
case 'evidence':{const e=evidence[state.index],ad=a.advice[state.index];kicker=`${a.name} / LIVE INTELLIGENCE`;title='Assess the evidence';subtitle='Check the source. Make your own call.';body=`<div class="evidence-progress">${evidence.map((x,i)=>`<span class="${i<state.index?'complete':i===state.index?'selected':''}"></span>`).join('')}<b>${state.index+1}/6</b></div><article class="intel-card"><div class="intel-id">CLASSIFIED　/　E-0${state.index+1}</div><h2>${e.title}</h2><p class="intel-claim">${e.claim}</p><button class="source-button" data-mobile="source"><span><small>INSPECT SOURCE ${state.verified[state.index]?'✓ REVIEWED':''}</small>${e.source}</span><b>↗</b></button><div class="ai-radio"><div class="ai-avatar">${a.symbol}</div><div><small>${a.name} RECOMMENDS <b class="${ad?'good':'bad'}">${ad?'TRUST':'DON’T TRUST'}</b></small><p>${ad?e.yes:e.no}</p></div></div></article>`;dock=`<div class="dual">${gameButton('× DON’T TRUST','answer:false',true)}${gameButton('✓ TRUST','answer:true')}</div><small>Your judgment is recorded. Next clue follows.</small>`;break;}
case 'decision':kicker='FINAL ORDER / YOU HAVE COMMAND';title='Issue your orders';subtitle='One route. One final decision.';body=`<div class="route-options">${routes.map((r,i)=>`<button class="route-choice" data-action="route:${i}"><span class="route-icon">${['◷','↗','⇢'][i]}</span><span><b>${r.name}</b><small>${r.cn}</small><em>${r.risk}</em></span><strong>+${[60,20,55][i]}<small>MIN</small></strong></button>`).join('')}</div><div class="radio"><i>${a.symbol}</i><p><b>${a.name} RECOMMENDS</b>${a.route}. The final call is yours.</p></div>`;dock='<small>Tap a route to issue your final order.</small>';break;
case 'outcome':{const outcomes={balanced:['◎','Safe passage','SAFE PASSAGE','You cleared the storm core and reached Port Helios on time.','16:30','ON TIME'],delayed:['◈','Safe, but late','SAFE, BUT LATE','Your crew is safe. The longer route missed the delivery window by 25 minutes.','17:05','25 MIN LATE'],storm:['⚠','Caught in the storm','CAUGHT IN THE STORM','The storm did not clear. Holding position exposed the vessel to unsafe seas. Mission aborted.','ABORTED','UNSAFE'],timeout:['⌛','Time ran out','COMMAND WINDOW LOST','No orders arrived in time. The vessel has begun emergency procedures.','NO ORDER','TIMEOUT']}[state.outcome];kicker=outcomes[2];title=outcomes[1];body=`<div class="result-medal ${state.outcome!=='balanced'?'warning':''}">${outcomes[0]}</div><p class="result-copy">${outcomes[3]}</p><div class="result-stats"><div><small>ARRIVAL</small><b>${outcomes[4]}</b></div><div><small>MISSION STATUS</small><b>${outcomes[5]}</b></div></div>`;dock=gameButton('OPEN DEBRIEF　→','debrief');break;}
case 'debrief':{const correct=state.answers.filter((v,i)=>v===evidence[i].truth).length,verified=state.verified.filter(Boolean).length;const agree=state.agent===null?0:state.answers.filter((v,i)=>v===a.advice[i]).length;kicker='AFTER ACTION / Debrief';title='Every judgment counts';subtitle=state.agent===null?'No advisor selected':`${a.name} · ${state.decision===null?'No final order':routes[state.decision].name}`;body=`<div class="summary-score"><strong>${correct}<span>/ 6</span></strong><div>Correct judgments<small>${state.answers.length} reviewed · ${agree} agreed with AI</small></div></div><div class="review-metrics"><div><span>Source checks</span><b>${verified}/6</b><p>${verified===6?'All original records inspected.':'Check origin, date and corroboration.'}</p></div><div><span>Decision process</span><b>COMPLETE</b><p>No time limit was active for this operation.</p></div></div><div class="radio"><i>◈</i><p><b>AI TRUST CALIBRATION</b>${correct>=5?'You distinguished reliable evidence from misleading claims. Keep thinking independently.':'Confidence is not reliability. Check outdated records and anonymous claims first.'}</p></div><button class="audit-button" data-mobile="report">REVIEW ALL 6 CLUES　↗</button>`;dock=gameButton('PLAY AGAIN　↻','reset');break;}}
return `<section class="game-screen ${state.screen}"><div class="screen-title"><div class="eyebrow">${kicker}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="play-content">${body}</div><div class="game-dock">${dock}</div></section>`;}
function overlay(){if(sourceOpen&&state.screen==='evidence'){const e=evidence[state.index];return `<div class="scrim"><section class="bottom-sheet" role="dialog" aria-modal="true" aria-label="Source record"><div class="sheet-handle"></div><div class="eyebrow">SOURCE VERIFICATION</div><h2>Source record</h2><div class="sheet-source">${e.source}</div><p>${e.detail}</p><div class="sheet-warning">◷ Timer disabled</div><button class="btn" data-mobile="close">BACK TO EVIDENCE</button></section></div>`;}if(reportOpen&&state.screen==='debrief')return `<div class="scrim"><section class="bottom-sheet audit-sheet" role="dialog" aria-modal="true" aria-label="Evidence review"><div class="sheet-handle"></div><div class="sheet-title"><h2>Evidence review</h2><button class="icon-btn" data-mobile="close" aria-label="Close review">×</button></div><div class="audit-list">${evidence.map((e,i)=>`<article><small>0${i+1} / ${state.verified[i]?'Source inspected':'Source not inspected'}</small><h3>${e.title}</h3><p>Your call: ${i<state.answers.length?(state.answers[i]?'TRUST':'DON’T TRUST'):'Not reviewed'} · <span class="${e.truth?'good':'bad'}">Verdict: ${e.truth?'Reliable':'Unreliable'}</span></p><p>AI: ${state.agent===null?'No advisor':agents[state.agent].advice[i]?'TRUST':'DON’T TRUST'}</p><p>${e.why}</p></article>`).join('')}</div></section></div>`;return '';}
render=function(){const view=state.screen+':'+state.index,changed=view!==lastView;lastView=view;if(changed){sourceOpen=false;reportOpen=false;}document.getElementById('app').innerHTML=`<div class="game-device"><div class="sea-background"><div class="radar-sweep"></div><div class="sea-grid"></div></div><header class="game-hud"><div class="hud-brand">◈ <span>MERIDIAN<small>${stageNames[state.screen]}</small></span></div><div class="timer"><div class="clock" role="status" aria-label="Countdown disabled"></div></div><div class="hud-controls">${controls()}</div></header>${mobileView()}${overlay()}<div class="home-indicator"></div></div>`;updateTimer();if(changed)gameAudio.sync();if(sourceOpen||reportOpen){document.querySelector('.game-screen').inert=true;document.querySelector('.hud-controls').inert=true;document.querySelector('[data-mobile="close"]')?.focus();}};
document.addEventListener('click',e=>{const target=e.target.closest('[data-mobile]');if(!target){if(e.target.closest('[data-action]'))tone();return;}const action=target.dataset.mobile;if(action==='fullscreen'){immersive=!immersive;document.body.classList.toggle('immersive',immersive);if(!immersive&&document.fullscreenElement)document.exitFullscreen?.();else if(immersive&&document.fullscreenEnabled)document.querySelector('.game-device').requestFullscreen?.().catch(()=>{});return;}if(action==='music'||action==='effects'){gameAudio.toggle(action);render();return;}if(!guard())return;if(action==='previous')advisorPreview=(advisorPreview+2)%3;if(action==='next')advisorPreview=(advisorPreview+1)%3;if(action.startsWith('preview:'))advisorPreview=Number(action.split(':')[1]);if(action==='source'&&state.screen==='evidence'){state.verified[state.index]=true;sourceOpen=true;}if(action==='report')reportOpen=true;if(action==='close'){sourceOpen=false;reportOpen=false;}tone();render();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(sourceOpen||reportOpen)){sourceOpen=false;reportOpen=false;render();}if(e.key==='Tab'&&(sourceOpen||reportOpen)){e.preventDefault();document.querySelector('[data-mobile="close"]')?.focus();}});
let touchStartX=null;document.addEventListener('touchstart',e=>{if(state.screen==='agents')touchStartX=e.touches[0].clientX;},{passive:true});document.addEventListener('touchend',e=>{if(state.screen==='agents'&&touchStartX!==null){let d=e.changedTouches[0].clientX-touchStartX;if(Math.abs(d)>60){advisorPreview=(advisorPreview+(d<0?1:2))%3;gameAudio.cue('switch');render();}touchStartX=null;}},{passive:true});
render();
